import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2020-01-07 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2020-01-07 :: Crimson SeaStor OSD Weekly Meeting","date":"2020-01-07T00:00:00.000Z","updated":"2020-01-11T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-07_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2020/2020-01-07_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-01-07_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function o(n,e,s,_,h,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议主要讨论了Ceph分布式存储系统的多个开发和优化议题，包括代码适配、性能优化、错误修复以及新功能的探索。会议中，各研发人员分享了他们的工作进展、遇到的问题以及后续的行动计划。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>代码适配与优化</strong></p><ul><li>研发人员正在调整Petri免疫算法，移除了对Alice ale的依赖，并改进CBT（Ceph Block Device）与slob（Simple List of Blocks）的集成。</li><li>讨论了使用slot和locator设计来优化内部节点的分割过程。</li></ul></li><li><p><strong>性能与稳定性改进</strong></p><ul><li>针对Ceph的锁定机制进行了讨论，旨在在不破坏兼容性的前提下改进锁定顺序和超时管理。</li><li>分析了DBT KQP巨大页面后台未启用导致的额外内存复制问题，探讨了如何通过配置来实现真正的零拷贝。</li></ul></li><li><p><strong>编译与兼容性问题</strong></p><ul><li>修复了导致ARM编译失败的代码变更，并强调了保持向后兼容性的重要性。</li><li>讨论了使用clunk格式和crank格式化工具来统一代码风格的可能性。</li></ul></li><li><p><strong>新功能探索</strong></p><ul><li>探讨了使用Chelsea和Archery来表示OSD（Object Storage Daemon）结构的设计思路，特别是如何简化存储结构和I/O处理机制。</li><li>讨论了利用混合逻辑时钟（HLC）来实现轻量级快照的可能性。</li></ul></li><li><p><strong>网络与内存优化</strong></p><ul><li>讨论了TCP/IP堆栈中套接字放置的问题，特别是如何在多核环境中优化套接字的分配。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>将继续优化Ceph的锁定机制，确保在不破坏兼容性的前提下提高性能。</li><li>将探索使用clunk格式和crank格式化工具来统一代码风格，以提高代码质量和开发效率。</li><li>将深入研究使用Chelsea和Archery来优化OSD结构，特别是如何实现轻量级快照和简化I/O处理。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>各研发人员将继续他们的工作，并在下一次会议前提交更新的代码和文档。</li><li>将安排进一步的讨论，以解决网络和内存优化中的具体问题。</li><li>将评估和测试新的设计思路，确保它们能够有效地集成到Ceph系统中。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>会议中还提到了具体的错误修复和代码审查请求，强调了持续集成和测试的重要性。</li><li>鼓励团队成员在遇到问题时及时沟通，并利用邮件列表和文档共享来提高协作效率。</li></ul><p>本次会议为Ceph项目的持续改进和发展奠定了基础，确保了团队在面对技术挑战时能够保持高效和协作。</p>',12)])])}const d=l(r,[["render",o]]);export{u as __pageData,d as default};
